def Proposition_3_1 (μ : Measure X) [SigmaFinite μ] : Prop :=
  ∀ (s : Set (Lp ℝ 1 μ)) (z : Lp ℝ 1 μ), IsLUB s z →
    ∃ c : Set (Lp ℝ 1 μ), c ⊆ s ∧ c.Countable ∧ IsLUB c z

